import{t as e}from"./jsx-runtime-lw2jiZar.js";import{C as t,D as n,E as r,I as i,L as a,M as o,N as s,O as c,P as l,S as u,b as d,g as f,k as p,l as m,n as h,o as g,p as _,t as v,x as y,y as b}from"./shared-CsAEn-Fy.js";var x=e();function S({module:e}){return(0,x.jsxs)(s,{children:[(0,x.jsx)(o,{variant:`project`,chip:e??`Блок 3 · Функции и инструменты`,title:`13.1. Отправляем код на GitHub`,intro:`Опубликуем существующий локальный commit и проверим, что на GitHub появилась именно эта версия проекта.`}),(0,x.jsxs)(l,{number:`00`,title:`От локальной истории к серверной копии`,children:[(0,x.jsx)(c,{children:`В предыдущем занятии мы подготовили локальный commit проекта StudyHub. Теперь разберём, как передать эту версию на GitHub и как проверить её там.`}),(0,x.jsx)(p,{variant:`connected`,items:[{title:`Точка старта`,description:`В том же clone есть main.py, .gitignore и предыдущий commit; перед отправкой сверим URL origin и имя активной ветки.`},{title:`Новый вопрос`,description:`Как опубликовать существующий commit в выбранной ветке и проверить, что GitHub показывает ту же версию?`},{title:`Результат`,description:`Опубликуем commit в своём репозитории и сверим адрес, ветку, полный ID и файлы.`}]}),(0,x.jsx)(`p`,{children:`Локальный commit даёт точку сравнения с серверной историей. Мы сначала выясним направление передачи, а после публикации проверим GitHub по фактическим данным проекта. Если исходные значения расходятся, сначала уточним причину и отложим push.`})]}),(0,x.jsxs)(l,{number:`01`,title:`Три разных состояния проекта`,children:[(0,x.jsx)(`p`,{children:`Сначала разделим сохранённый файл, commit в локальной истории и копию истории на GitHub. Когда мы нажимаем Save в редакторе, меняется файл на диске. Commit фиксирует выбранное состояние в истории Git на нашем компьютере. Push передаёт уже созданную историю на выбранный сервер и обновляет там ветку. Это три отдельные границы.`}),(0,x.jsx)(`p`,{children:`Представим рабочую тетрадь. Исправленная страница лежит на столе, запись в журнале хранит выбранный снимок, а отправленная копия находится в другом месте. Если мы исправили страницу после записи в журнал, старая запись не меняется автоматически. Так же и незакоммиченная правка не входит в уже созданный commit, а push не добавляет в историю правки, которых в commit не было.`}),(0,x.jsxs)(`p`,{children:[(0,x.jsx)(`code`,{children:`HEAD`}),` означает специальное имя текущей точки истории Git. Обычно это последний commit выбранной ветки.`]}),(0,x.jsx)(v,{caption:`Путь уже созданного commit до GitHub`,children:(0,x.jsxs)(g,{label:`Локальный commit отправляется в удалённую ветку`,children:[(0,x.jsxs)(m,{title:`Локальная ветка`,children:[(0,x.jsx)(`p`,{children:`HEAD указывает на созданный commit`}),(0,x.jsx)(`code`,{children:`main.py + .gitignore`})]}),(0,x.jsx)(h,{label:`push: remote и направление ветки`}),(0,x.jsxs)(m,{title:`Ветка на GitHub`,shape:`database`,children:[(0,x.jsx)(`p`,{children:`Сервер получает эту историю`}),(0,x.jsx)(`code`,{children:`тот же commit`})]})]})}),(0,x.jsx)(`p`,{children:`Слова «commit уже есть» важны: в этом занятии мы не готовим файлы и не создаём снимок. Мы отправляем имеющийся снимок. Это похоже на отправку запечатанной версии: после нового изменения потребуется новый commit, но сейчас наша цель только проверить доставку уже выбранной версии.`}),(0,x.jsx)(d,{question:`Файл сохранён, локальный commit создан, но push ещё не выполняли. Где сейчас подтверждён этот commit?`,options:[`Только в локальной истории`,`Уже на GitHub, потому что git status чистый`,`В новом commit, который Git создаст при push`],correctIndex:0,explanation:`Сохранение и локальная история не подтверждают серверную копию. Push передаёт существующую историю, а не создаёт новый commit.`}),(0,x.jsx)(r,{tone:`info`,children:`Пустой git status сообщает только об отсутствии локальных незакоммиченных изменений. Он не показывает, совпадает ли GitHub с нашим HEAD.`}),(0,x.jsx)(`p`,{children:`Для быстрой проверки мы читаем состояния по очереди. Если файл сохранён, но commit ещё не создан, изменения остаются вне локальной истории. Если commit создан, он уже находится в локальной истории и может быть указан через HEAD. Если тот же commit доступен в выбранной ветке GitHub, он опубликован. В этой теме мы работаем с последним переходом, а первые два считаем подготовленной опорой и проверяем перед ним.`})]}),(0,x.jsxs)(l,{number:`02`,title:`Проверяем адрес, ветку и commit`,children:[(0,x.jsx)(`p`,{children:`До отправки мы проверяем, из какой папки работаем, куда ведёт remote и какая ветка активна. Имя origin часто назначают главному удалённому репозиторию, но это всего лишь сохранённая метка. Важно посмотреть URL рядом с ней. У одной метки могут отдельно отображаться адрес для получения и адрес для отправки, поэтому сверяем строку push.`}),(0,x.jsx)(`p`,{children:`Ветку тоже читаем из текущего clone, а не угадываем по примеру. В нашем пустом private-репозитории на GitHub пока может не быть ветки. Локальная ветка уже содержит commit, и именно её имя будет источником отправки. Если команда не показывает имя, мы не находимся на обычной локальной ветке и пока не запускаем push.`}),(0,x.jsx)(`p`,{children:`Эти команды читают локальные настройки и состояние. git remote -v печатает URL отдельно для fetch и push; для публикации нас интересует точная строка push. git branch --show-current называет активную локальную ветку, а git log -1 --format=%H выдаёт полный ID верхнего commit. Пустой результат команды о ветке означает, что HEAD сейчас не на именованной ветке. В таком состоянии мы не угадываем имя и не отправляем команду из примера.`}),(0,x.jsx)(b,{title:`проверка перед отправкой`,lines:[{cmd:`git status --short`},{out:`(пустой вывод: незакоммиченных изменений нет)`},{cmd:`git branch --show-current`},{out:`main`},{cmd:`git remote -v`},{out:`origin  https://github.com/example-user/studyhub.git (fetch)`},{out:`origin  https://github.com/example-user/studyhub.git (push)`},{cmd:`git log -1 --format=%H`},{out:`a14c9e2b7f048c6124d03fae8b6c91d08b4e5c71`}]}),(0,x.jsx)(`p`,{children:`Здесь main является именем основной ветки нашего проекта, example-user обозначает условного владельца, а hash показывает полный ID последнего commit. В своём clone мы проверяем реальные значения, не копируя адрес и ID из демонстрации. Полный ID помогает отличить один снимок от другого, даже если сообщения commit похожи.`}),(0,x.jsx)(`p`,{children:`Представим адресную книгу: имя «origin» похоже на подпись у записи, а URL является самим адресом. Подпись удобна, но не защищает от ошибки, если в записи сохранился чужой адрес. Поэтому перед публикацией проверяем проект, владельца и репозиторий по URL. Название папки на компьютере не подтверждает, кому принадлежит remote.`}),(0,x.jsx)(p,{items:[{title:`origin`,description:`Имя remote в настройках Git. URL под ним указывает фактическое место обмена.`},{title:`Текущая ветка`,description:`Локальная линия commit, которую мы проверили в этом clone.`},{title:`Полный ID`,description:`Точный commit из локального HEAD, с которым затем сравним GitHub.`}]}),(0,x.jsx)(_,{prompt:`Сопоставим команду с тем фактом, который она показывает.`,leftTitle:`Команда`,rightTitle:`Результат`,pairs:[{left:`git remote -v`,right:`URL remote для получения и отправки`},{left:`git branch --show-current`,right:`Имя активной локальной ветки`},{left:`git log -1 --format=%H`,right:`Полный ID текущего верхнего commit`},{left:`git status --short`,right:`Незакоммиченные локальные изменения`}],explanation:`Теперь отдельно известны адрес назначения, локальная ветка, commit и состояние рабочей папки.`}),(0,x.jsx)(`p`,{children:`Если URL не принадлежит нашему пустому репозиторию, мы останавливаемся. Если в status видны неожиданные изменения, сначала выясняем, откуда они взялись. Push передаёт commit, а не каждую строку из открытой папки, но отправлять неизвестную историю или в неизвестное место нельзя.`})]}),(0,x.jsxs)(l,{number:`03`,title:`Первый push и направление ветки`,children:[(0,x.jsxs)(`p`,{children:[`Сохраняем имя текущей ветки своего проекта. Сначала узнаем его командой `,(0,x.jsx)(`code`,{children:`git branch --show-current`}),`. В примерах это `,(0,x.jsx)(`code`,{children:`main`}),`, но в вашем репозитории имя может отличаться. Для push используем фактическое имя, а на GitHub затем выбираем ту же ветку.`]}),(0,x.jsx)(r,{tone:`info`,children:`Переименовывать ветку ради примера не требуется. Если команда не вывела имя, сначала выясняем состояние репозитория; push не выполняем, пока не определены текущая ветка и существующий commit.`}),(0,x.jsxs)(`p`,{children:[`Для первого push в наш пустой репозиторий указываем remote и имя текущей ветки: `,(0,x.jsx)(`code`,{children:`git push --set-upstream origin ИМЯ_ВЕТКИ`}),`. Только если команда проверки вывела main, используем`,` `,(0,x.jsx)(`code`,{children:`git push --set-upstream origin main`}),`. Git отправит эту ветку в origin под тем же именем.`]}),(0,x.jsx)(`p`,{children:`Команда передаёт уже созданный commit. Флаг --set-upstream после успешной отправки запоминает, что локальная ветка связана с одноимённой веткой в origin. Для примера main это origin/main.`}),(0,x.jsx)(f,{prompt:`В этом примере git branch --show-current вывела main. Что укажем после origin?`,before:`git push --set-upstream origin `,after:``,options:[`main`,`origin`,`--force`],answer:`main`,explanation:`После origin указываем имя ветки, которое получили из своего clone командой git branch --show-current.`}),(0,x.jsx)(`p`,{children:`Origin называет удалённый репозиторий, а upstream обозначает ветку этого репозитория, за которой следит локальная ветка. Флаг --set-upstream сохраняет эту связь, но сам по себе не подтверждает, что адрес и аккаунт выбраны верно.`}),(0,x.jsxs)(r,{tone:`info`,children:[`Дополнительная справка: если имена локальной и удалённой веток различаются, их можно сопоставить через двоеточие:`,(0,x.jsx)(`code`,{children:`git push --set-upstream origin ЛОКАЛЬНАЯ:УДАЛЁННАЯ`}),`. Git называет такую запись refspec: слева указан источник, справа назначение. Для примера выше имена одинаковы, поэтому двоеточие не нужно.`]}),(0,x.jsx)(b,{title:`схематичный успешный ответ Git`,lines:[{cmd:`git push --set-upstream origin main`},{out:`Enumerating objects: 3, done.`},{out:` * [new branch]      main -> main`},{out:`branch 'main' set up to track 'origin/main'.`}]}),(0,x.jsx)(`p`,{children:`Вывод Git сообщает об отправке, а страница GitHub подтверждает опубликованную версию. Если push отклонён или remote неожиданно содержит другую историю, сначала выясняем причину.`}),(0,x.jsxs)(r,{tone:`info`,children:[`Для справки: `,(0,x.jsx)(`a`,{href:`https://git-scm.com/docs/git-push`,target:`_blank`,rel:`noreferrer`,children:`описание git push в Git`}),` `,`и `,(0,x.jsx)(`a`,{href:`https://docs.github.com/en/get-started/using-git/pushing-commits-to-a-remote-repository`,target:`_blank`,rel:`noreferrer`,children:`инструкция GitHub по push`}),`.`]})]}),(0,x.jsxs)(l,{number:`04`,title:`Автор commit, вход и право записи`,children:[(0,x.jsx)(`p`,{children:`На публикации встречаются три разные роли. Автор commit записан в метаданных локального снимка. Аккаунт подтверждает сетевой запрос к GitHub. Разрешение на запись определяет, может ли этот аккаунт менять конкретный репозиторий. Совпадение этих ролей возможно, но одна не доказывает другую.`}),(0,x.jsx)(`p`,{children:`Это похоже на отправку посылки. Подпись на вложенной записке говорит, кто подготовил содержимое. Документ, который предъявили на стойке, указывает, кто сейчас проходит проверку. А правила доступа решают, куда этому человеку разрешено положить посылку. Подпись автора не становится паролем от GitHub и не выдаёт право записи.`}),(0,x.jsxs)(a,{children:[(0,x.jsx)(i,{badge:`COMMIT`,title:`Автор`,children:`user.name и user.email попадают в сведения о commit. Они не выполняют вход в GitHub.`}),(0,x.jsx)(i,{badge:`HTTPS`,title:`Аккаунт`,children:`Git или Git Credential Manager подтверждает учётную запись для сетевой операции через HTTPS, защищённое сетевое соединение.`}),(0,x.jsx)(i,{badge:`REPOSITORY`,title:`Доступ`,children:`У вошедшего аккаунта должно быть право записи именно в проверенный репозиторий.`})]}),(0,x.jsx)(`p`,{children:`Если commit публичен, другие люди могут увидеть его, но это не означает, что им разрешено отправлять свои commit в исходный репозиторий. Если репозиторий частный, аккаунт должен иметь доступ к нему. GitHub может связать адрес автора с профилем, когда этот адрес добавлен в аккаунт, но такая связь тоже не выполняет вход. Для push сервер проверяет сетевой аккаунт и разрешение именно на выбранный проект.`}),(0,x.jsx)(`p`,{children:`При HTTPS Git Credential Manager может открыть браузер для штатного входа. Следуем системному запросу в своём браузере и не включаем секреты в команду, код, текст урока или переписку. У GitHub пароль аккаунта не является способом авторизации в командной строке; используем поддерживаемый менеджер учётных данных. Самостоятельно создавать токен в этом задании не требуется.`}),(0,x.jsx)(u,{statement:`Если имя автора в git log совпало с именем ученика в GitHub, это доказывает, что push выполнен его аккаунтом и у него есть право записи.`,isTrue:!1,explanation:`Git хранит автора в commit отдельно от сетевой авторизации. Доступ проверяется для аккаунта, которым мы вошли, и конкретного remote.`}),(0,x.jsx)(`p`,{children:`Если окно входа открылось, это ещё не доказывает право записи. Если вошедший аккаунт не может изменять репозиторий, GitHub откажет. Тогда проверим, тот ли аккаунт открыт и принадлежит ли ему выбранный private-репозиторий. Не переписываем автора существующего commit ради исправления входа и не просим пользователя передавать пароль или токен.`}),(0,x.jsx)(r,{tone:`warn`,children:`Не вставляем access token, пароль, резервный код или содержимое credential manager в терминал, файл проекта, скриншот или сообщение. При неожиданном запросе останавливаемся и уточняем штатный способ входа.`})]}),(0,x.jsxs)(l,{number:`05`,title:`Ошибки показывают разные границы`,children:[(0,x.jsx)(`p`,{children:`Перед диагностикой мы читаем, на каком шаге остановился push. Неверный URL указывает на адрес назначения. Ошибка refspec или сообщение, что ветка не найдена, чаще требует сверить имя локальной ветки и наличие commit. Ошибка аутентификации относится к сетевому входу, а отказ в разрешении записи к правам аккаунта на remote. Переименование автора не исправляет вход, повторный clone не выдаёт права, а новая ветка не чинит неверный URL.`}),(0,x.jsx)(`p`,{children:`Текст ошибки полезен как подсказка, но мы проверяем её по состоянию проекта. Например, при Repository not found сравниваем URL и аккаунт, которому виден private-репозиторий. При src refspec does not match any сначала сверяем реальное имя ветки и commit. При Permission denied выясняем, какой аккаунт прошёл вход и есть ли у него доступ.`}),(0,x.jsx)(`p`,{children:`Один и тот же видимый отказ иногда допускает больше одной причины. Например, GitHub может сообщить, что репозиторий не найден, если в URL опечатка или текущий аккаунт не видит private-репозиторий. Поэтому мы проверяем обе стороны: сначала адрес, затем доступность проекта для вошедшего аккаунта. Такая последовательность помогает не менять историю, пока не установлено, что именно отказало.`}),(0,x.jsx)(t,{code:`$ git push --set-upstream origin main
remote: Permission to example-user/studyhub.git denied to another-account`,question:`Какую проверку выполнить первой, если URL проверен, а сообщение называет другой аккаунт?`,options:[`Сверить аккаунт в штатном GitHub-входе и его право записи`,`Заменить user.name и создать новый commit`,`Повторить push с --force`],correctIndex:0,explanation:`Отказ относится к аккаунту или его доступу. Автор commit остаётся сведением о снимке, а force изменил бы риск истории без связи с причиной.`}),(0,x.jsx)(`p`,{children:`Сообщение non-fast-forward означает, что серверная ветка содержит историю, которой нет в нашей локальной ветке. В текущем маршруте remote ожидался пустым, поэтому такой случай означает, что исходное состояние отличается от плана. Мы останавливаем push и передаём вопрос на отдельное согласование истории. Не используем pull, merge, rebase или force наугад.`}),(0,x.jsx)(`p`,{children:`Разбор ошибок проходит на подготовленных примерах. Мы не ломаем живой remote ради практики и не проверяем права записью в чужой проект. Для каждой ошибки называем только ближайшую безопасную проверку, затем возвращаемся к рабочему маршруту, когда исходное состояние совпадает с проверками из начала занятия.`})]}),(0,x.jsxs)(l,{number:`06`,title:`Подтверждаем серверную версию`,children:[(0,x.jsx)(`p`,{children:`После push открываем именно свой GitHub-репозиторий и выбираем опубликованную ветку. Сначала сравним полный ID commit на странице с ID, который получили из локального log. Затем посмотрим содержимое main.py и .gitignore. В задании это Hello world и правила для __pycache__/ и *.pyc, подготовленные в предыдущих шагах.`}),(0,x.jsxs)(`figure`,{style:{width:`100%`,maxWidth:`960px`,margin:`24px auto`},children:[(0,x.jsx)(`a`,{href:`https://docs.github.com/en/repositories/configuring-branches-and-merges-in-your-repository/managing-branches-in-your-repository/viewing-branches-in-your-repository?apiVersion=2022-11-28`,target:`_blank`,rel:`noreferrer`,style:{display:`flex`,justifyContent:`center`},children:(0,x.jsx)(`img`,{src:`https://docs.github.com/assets/cb-36152/images/help/repository/file-tree-view-branch-dropdown-expanded.png`,alt:`Пример GitHub: открыто меню выбора ветки над списком файлов; текущая ветка main, ниже видна другая ветка`,style:{display:`block`,maxWidth:`100%`,height:`auto`,borderRadius:`8px`}})}),(0,x.jsxs)(`figcaption`,{style:{marginTop:`8px`},children:[(0,x.jsx)(`strong`,{children:`1. Выберем ветку.`}),` В меню над списком файлов выберем ветку из команды push. На снимке показаны примерные имена, поэтому сверим свою ветку с именем из команды.`]})]}),(0,x.jsxs)(`figure`,{style:{width:`100%`,maxWidth:`960px`,margin:`24px auto`},children:[(0,x.jsx)(`a`,{href:`https://docs.github.com/en/pull-requests/how-tos/commit-changes/troubleshooting-commits`,target:`_blank`,rel:`noreferrer`,style:{display:`flex`,justifyContent:`center`},children:(0,x.jsx)(`img`,{src:`https://docs.github.com/assets/cb-48469/images/help/commits/commits-page.png`,alt:`Пример GitHub: над списком файлов показана выбранная ветка main и выделенная ссылка на список commits`,style:{display:`block`,maxWidth:`100%`,height:`auto`,borderRadius:`8px`}})}),(0,x.jsxs)(`figcaption`,{style:{marginTop:`8px`},children:[(0,x.jsx)(`strong`,{children:`2. Откроем commits.`}),` Нажмём ссылку с количеством commits над списком файлов, затем выберем сообщение нужного commit. Это официальные примеры интерфейса GitHub Docs.`]})]}),(0,x.jsxs)(`p`,{children:[(0,x.jsx)(`strong`,{children:`3. Найдём полный ID.`}),` На странице выбранного commit найдём адрес вида`,` `,(0,x.jsx)(`code`,{children:`https://github.com/OWNER/REPOSITORY/commit/FULL_COMMIT_ID`}),`. Сравним часть после /commit/ с полным ID из git log. В списке commits может отображаться только короткая запись.`]}),(0,x.jsx)(`p`,{children:`Три признака должны сходиться: адрес ведёт в ожидаемый репозиторий, нужная ветка указывает на этот commit, а GitHub показывает ожидаемые файлы. Если строка приветствия или правила отличаются, значит мы сравниваем не тот commit либо не ту ветку. Возвращаемся к именам и ID, не исправляем это новым файлом или новым commit.`}),(0,x.jsx)(`p`,{children:`Успешный ответ терминала подтверждает, что команда получила положительный ответ от remote, но не показывает, какую страницу мы открыли в браузере. Чистый status говорит только о локальных файлах. Поэтому доказательство результата состоит из локального полного ID и фактической страницы GitHub с тем же ID, веткой и содержимым двух файлов.`}),(0,x.jsx)(`p`,{children:`Короткого фрагмента недостаточно для этой сверки. После адреса и полного ID проверьте main.py и .gitignore в выбранной ветке. Так мы убеждаемся, что на GitHub находится нужная версия проекта.`}),(0,x.jsx)(_,{prompt:`Соберём порядок финальной сверки.`,leftTitle:`Что сверяем`,rightTitle:`С чем сравниваем`,pairs:[{left:`Адрес страницы`,right:`Проверенный push URL remote origin`},{left:`Ветка на GitHub`,right:`Имя выбранной целевой ветки`},{left:`Полный commit ID`,right:`Локальный HEAD из git log`},{left:`main.py и .gitignore`,right:`Ожидаемые файлы после занятий 12.1 и 13`}],explanation:`Только совпадение адреса, ветки, commit и файлов подтверждает передачу именно ожидаемой версии.`}),(0,x.jsx)(`p`,{children:`В следующем уроке работа продолжится с этим же Hello world-коммитом. Здесь мы проверяем только опубликованную версию.`}),(0,x.jsx)(y,{question:`Сформулируем проверку результата без просмотра ответа: какие четыре значения должны совпасть?`,hint:`Начнём с адреса remote и закончим файлами.`,answer:(0,x.jsx)(`p`,{children:`Сверяем адрес репозитория, имя ветки, полный ID commit и содержимое main.py вместе с .gitignore.`})}),(0,x.jsxs)(r,{tone:`info`,children:[`Дополнительная справка: `,(0,x.jsx)(`a`,{href:`https://git-scm.com/docs/git-config`,target:`_blank`,rel:`noreferrer`,children:`поля автора и commit в настройках Git`}),` и`,` `,(0,x.jsx)(`a`,{href:`https://docs.github.com/en/get-started/git-basics/caching-your-github-credentials-in-git`,target:`_blank`,rel:`noreferrer`,children:`вход через Git Credential Manager`}),`.`]})]}),(0,x.jsxs)(l,{number:`07`,title:`Что сделаем в практике`,children:[(0,x.jsx)(p,{variant:`connected`,items:[{title:`Проверим исходное состояние`,description:`Сверим clone, push URL, ветку и локальный commit.`},{title:`Отправим историю`,description:`После проверки направления выполним первый push в свой пустой remote.`},{title:`Подтвердим копию`,description:`Сравним на GitHub ветку, полный ID и два ожидаемых файла.`},{title:`Разберём отказы`,description:`На безопасных примерах назовём причину и следующую проверку.`}]}),(0,x.jsx)(`p`,{children:`Если clone, адрес или предыдущий commit не совпадают с проверками, сначала уточните исходное состояние. Push выполняйте после того, как все четыре факта из вступления совпали.`})]}),(0,x.jsx)(n,{points:[(0,x.jsx)(x.Fragment,{children:`Save, commit и push меняют разные состояния проекта.`}),(0,x.jsx)(x.Fragment,{children:`Перед push проверяем origin, локальную ветку и commit.`}),(0,x.jsx)(x.Fragment,{children:`Автор commit, аккаунт входа и право записи являются разными фактами.`}),(0,x.jsx)(x.Fragment,{children:`На GitHub сверяем адрес, ветку, полный ID и файлы.`})]})]})}export{S as Lesson13_1};